function firstBouquetDay(bloomDay: number[], m: number, k: number): number {
  if (m * k > bloomDay.length) return -1;
  const days = [...new Set(bloomDay)].sort((a, b) => a - b);
  for (const d of days) {
    let made = 0, run = 0;
    for (const b of bloomDay) {
      run = b <= d ? run + 1 : 0;
      if (run === k) { made++; run = 0; }
    }
    if (made >= m) return d;
  }
  return -1;
}

