function firstBouquetDay(bloomDay: number[], m: number, k: number): number {
  if (m * k > bloomDay.length) return -1;
  const canMake = (d: number): boolean => {
    let made = 0, run = 0;
    for (const b of bloomDay) {
      if (b <= d) {
        if (++run === k) { made++; run = 0; }
      } else {
        run = 0;
      }
    }
    return made >= m;
  };
  let lo = Math.min(...bloomDay), hi = Math.max(...bloomDay);
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (canMake(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

