        def can_make(d: int) -> bool:
            made = run = 0
            for b in bloomDay:
                if b <= d:
                    run += 1
                    if run == k:
                        made += 1
                        run = 0
                else:
                    run = 0
            return made >= m

        lo, hi = min(bloomDay), max(bloomDay)
        while lo < hi:
            mid = (lo + hi) // 2
            if can_make(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

